import json,glob,os,collections
T=r"C:/Users/sever/.claude/projects/C--Users-sever-documents-projeto2"
for f in sorted(glob.glob(T+"/*.jsonl")):
    seen={};models=collections.Counter();n_user=0
    for line in open(f,encoding="utf-8"):
        try:d=json.loads(line)
        except:continue
        if d.get("type")=="user" and isinstance(d.get("message",{}).get("content"),str): n_user+=1
        m=d.get("message") or {}
        if d.get("type")=="assistant" and m.get("usage"):
            seen[m.get("id")]=(m.get("model"),m["usage"])
    tot=collections.Counter()
    for mid,(model,u) in seen.items():
        models[model]+=1
        for k in("input_tokens","output_tokens","cache_creation_input_tokens","cache_read_input_tokens"):
            tot[k]+=u.get(k) or 0
    print(os.path.basename(f),dict(models),dict(tot),"prompts_texto:",n_user)
